const cleanTags=s=>{const seen=new Set(),o=[];for(const x of str(s,300).split(",")){const t=x.trim().replace(/\s+/g," ").slice(0,30);if(!t)continue;const q=t.toLowerCase();if(seen.has(q))continue;seen.add(q);o.push(t);if(o.length>=8)break}return o.join(",")};
