const cfCall=async(env,m,path,body)=>{const ac=new AbortController(),t=setTimeout(()=>ac.abort(),12000);try{const r=await fetch(cfBase(env)+path,{method:m,signal:ac.signal,headers:{"x-client-id":env.CASHFREE_APP_ID,"x-client-secret":env.CASHFREE_SECRET,"x-secret-key":env.CASHFREE_SECRET,"x-api-version":"2023-08-01","content-type":"application/json"},body:body?JSON.stringify(body):undefined});return{ok:r.ok,status:r.status,j:await r.json().catch(()=>({}))}}catch(e){return{ok:false,status:0,j:{}}}finally{clearTimeout(t)}};
const cfSign=async(secret,ts,raw)=>{const k=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]),m=await crypto.subtle.sign("HMAC",k,new TextEncoder().encode(ts+raw));let b="";new Uint8Array(m).forEach(x=>b+=String.fromCharCode(x));return btoa(b)};
const SHOPON=" AND (owner_id IS NULL OR owner_id NOT IN (SELECT user_id FROM shop_profiles WHERE disabled=1))",SHOPON2=SHOPON.replace(/owner_id/g,"shop_products.owner_id");
