const skuPart=x=>(String(x||"").replace(/[^A-Za-z0-9]/g,"").toUpperCase()+"XXX").slice(0,3);
async function autoSku(DB,own,cat){const ps=String(cat||"").split("\u203a").map(x=>x.trim()).filter(Boolean),pre=[own?"S"+(+own):"PS",...[0,1,2].map(i=>ps[i]?skuPart(ps[i]):"GEN")].join("-");
 const r=await DB.prepare("SELECT COUNT(*) n FROM shop_products WHERE sku LIKE ? ESCAPE '\\'").bind(pre.replace(/[\\%_]/g,"\\$&")+"-%").first();let n=(r&&r.n||0)+1;
 for(let i=0;i<50;i++,n++){const c=pre+"-"+String(n).padStart(4,"0"),x=await DB.prepare("SELECT id FROM shop_products WHERE sku=?").bind(c).first();if(!x)return c}return pre+"-"+Date.now()%100000}
/* Effective "change-of-mind return allowed": the product flag AND its category is not on the admin non-returnable list (setting nrc, items joined by "|", matched on the full category or its top level) */
const RETE="CASE WHEN returns=1 AND NOT EXISTS(SELECT 1 FROM shop_settings ns WHERE ns.k='nrc' AND ns.v<>'' AND (instr('|'||lower(ns.v)||'|','|'||lower(category)||'|')>0 OR instr('|'||lower(ns.v)||'|','|'||lower(CASE WHEN instr(category,' \u203a ')>0 THEN substr(category,1,instr(category,' \u203a ')-1) ELSE category END)||'|')>0)) THEN 1 ELSE 0 END";
const nrHit=(list,cat)=>{const L=String(list||"").toLowerCase().split("|").filter(Boolean),c=String(cat||"").toLowerCase().trim(),t=c.split(" \u203a ")[0].trim();return !!c&&(L.includes(c)||L.includes(t))};
/* Photos and videos a customer attaches to a return request. The table is created on first use, so no manual migration is needed. */
let RPOK=false;
async function ensureRP(DB){if(RPOK)return;try{await DB.prepare("CREATE TABLE IF NOT EXISTS shop_return_proofs(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER, kind TEXT, ct TEXT, data TEXT, r2 INTEGER DEFAULT 0, created_at INTEGER)").run();await DB.prepare("CREATE INDEX IF NOT EXISTS i_srp ON shop_return_proofs(order_id)").run();RPOK=true}catch(e){}}
const RKIND={change:"Changed my mind",damaged:"Damaged or defective",wrong:"Wrong item received",missing:"Item or part missing",notasdescribed:"Not as described",other:"Other problem"};
const RNEEDS=["damaged","wrong","missing","notasdescribed"];
const sniffRP=buf=>{const sg=(a,i)=>a.every((x,k)=>buf[i+k]===x);if(sg([255,216],0))return{kind:"image",ct:"image/jpeg"};if(sg([137,80,78,71],0))return{kind:"image",ct:"image/png"};if(sg([82,73,70,70],0)&&sg([87,69,66,80],8))return{kind:"image",ct:"image/webp"};if(sg([102,116,121,112],4)){const br=String.fromCharCode(...buf.subarray(8,12));return{kind:"video",ct:br==="qt  "?"video/quicktime":"video/mp4"}}if(sg([26,69,223,163],0))return{kind:"video",ct:"video/webm"};return null};
const PCOLS="id,owner_id,status,reject_note,stock,sku,title,category,price,shop_price,shop_mrp,mrp,options,returns,description,COALESCE(description_te,'') AS description_te,active,COALESCE(weight_g,250) AS weight_g,COALESCE(tags,'') AS tags,(SELECT id FROM shop_media m WHERE m.product_id=shop_products.id AND m.kind='image' ORDER BY m.sort,m.id LIMIT 1) AS cover";
const OCOLS=PCOLS.replace("options,returns,","options,"+RETE+" AS returns,").replace("price,","COALESCE(shop_price,price) AS price,").replace("shop_mrp,mrp,","COALESCE(shop_mrp,mrp) AS mrp,");
const PUBCOLS=PCOLS.replace("options,returns,","options,"+RETE+" AS returns,").replace("reject_note,","").replace("shop_price,shop_mrp,","");
const MAXV=26214400,MAXIMG=8;

const enc=s=>new TextEncoder().encode(s),hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join(""),rnd=n=>hex(crypto.getRandomValues(new Uint8Array(n)));
async function pbk(pw,salt){const k=await crypto.subtle.importKey("raw",enc(pw),"PBKDF2",false,["deriveBits"]);return hex(await crypto.subtle.deriveBits({name:"PBKDF2",salt:enc(salt),iterations:100000,hash:"SHA-256"},k,256))}
const shopCode=id=>"SH"+String(id).padStart(3,"0");
const stockOf=v=>{if(v===""||v===null||v===undefined)return null;const n=Math.round(+v);return n===n&&n>=0&&n<=100000?n:undefined};
async function couponOf(DB,code,ip){code=String(code||"").trim();if(!code)return{none:true};
 if(!/^[A-Za-z0-9]{3,20}$/.test(code))return{error:"This coupon code is not valid."};
 const tr=await DB.prepare("SELECT COUNT(*) n FROM shop_coupon_tries WHERE ip=? AND at>?").bind(ip,Date.now()-36e5).first();if(tr&&tr.n>=10)return{error:"Too many wrong codes. Please try again in an hour.",limited:true};
 const c=await DB.prepare("SELECT code,pct,kind,max_discount FROM shop_coupons WHERE code_uc=? AND active=1 AND (expires_at IS NULL OR expires_at>?)").bind(code.toUpperCase(),Date.now()).first();
 if(!c){await DB.prepare("INSERT INTO shop_coupon_tries(ip,at) VALUES(?,?)").bind(ip,Date.now()).run();return{error:"This coupon code is not valid or has expired."}}
 return{code:c.code,pct:c.pct,kind:c.kind==="fixed"?"fixed":"percent",max:c.max_discount||0}}
const discOf=(items,c)=>{let d=c.kind==="fixed"?c.pct:Math.floor(items*c.pct/100);if(c.kind!=="fixed"&&c.max>0)d=Math.min(d,c.max);return Math.max(0,Math.min(items-1,d))};
async function getSet(DB,env){const S={ctype:"percent",cval:num(env.SHOP_DEFAULT_MARKUP||20,0,500)||0,fee:num(env.SHOP_DELIVERY_FEE||0,0,5000)||0,free:0,ccost:0,cmin:60,minord:0,pins:"",nrc:"",slabs:"",zon:1,pc:10,fl:40,gl:70,xl:899,fs:60,gs:78,xs:1200,fo:60,go:78,xo:1200,zcity:"5000,50010",zstate:"50",rot:4,d0a:1,d0b:1,d1a:2,d1b:2,d2a:2,d2b:4,d3a:4,d3b:7,hpin:"500045",rl:0,rs:0,ro:0,qmax:2,cmax:2,tmax:12,lmax:6,pmax:2};
 try{const r=(await DB.prepare("SELECT k,v FROM shop_settings").all()).results;for(const x of r){if(x.k==="ctype")S.ctype=x.v==="fixed"?"fixed":"percent";else if(x.k==="pins")S.pins=String(x.v||"");else if(x.k==="nrc")S.nrc=String(x.v||"");else if(x.k==="slabs")S.slabs=String(x.v||"");else if(x.k==="zcity"||x.k==="zstate"||x.k==="hpin")S[x.k]=String(x.v||"");else if(x.k in S)S[x.k]=Number(x.v)||0}}catch(e){}return S}
const zoneOf=(S,pin)=>{pin=String(pin||"");const has=l=>String(l||"").split(",").filter(Boolean).some(x=>pin.startsWith(x));return has(S.zcity)?"l":has(S.zstate)?"s":"o"};
/* Courier charge kept on a change-of-mind return (delivery + pickup), by area. Never less than the delivery charge the customer already paid. */
const retChargeOf=(S,pin)=>{const z=zoneOf(S,pin);return z==="l"?S.rl:z==="s"?S.rs:S.ro};
const feeOf=(S,v,pin)=>{if(S.zon){const z=zoneOf(S,pin),f=z==="l"?S.fl:z==="s"?S.fs:S.fo,g=z==="l"?S.gl:z==="s"?S.gs:S.go,x=z==="l"?S.xl:z==="s"?S.xs:S.xo;if(x>0&&v>x)return 0;return S.pc>0&&g>0?Math.min(g,Math.max(f,Math.round(v*S.pc/100))):f}if(S.free>0&&v>=S.free)return 0;for(const r of String(S.slabs||"").split(",")){const [u,f]=r.split(":").map(Number);if(u>0&&v<=u)return f||0}return S.fee};
const addC=(x,S)=>{x=Number(x)||0;return x>0?Math.ceil(S.ctype==="fixed"?x+S.cval:x*(1+S.cval/100)-1e-9):0};
const priceFill=(b,S)=>{const sp=+b.shop_price||0,sm=+b.shop_mrp||0,bl=v=>v===undefined||v===null||String(v).trim()==="";if(b.owner_id&&sp>0){if(bl(b.price))b.price=addC(sp,S);if(sm>0&&bl(b.mrp))b.mrp=addC(sm,S)}else if(!b.owner_id&&sp>0){if(bl(b.price))b.price=sp;if(sm>0&&bl(b.mrp))b.mrp=sm}};
const manualOf=(f,S)=>f.own&&f.sp>0?((f.price!==addC(f.sp,S)||(f.sm>0&&f.mrp!==addC(f.sm,S)))?1:0):0;
const wtOf=b=>{if(b.weight===undefined)return undefined;const v=b.weight;if(v===null||String(v).trim()==="")return null;const n=num(v,1,50000);return n===null?"bad":n};
const fieldsOf=b=>{const t=str(b.title,120),price=num(b.price,1,1e6),mrp=num(b.mrp||0,0,1e6),sm=num(b.shop_mrp||0,0,1e6),s0=b.shop_price,sp=(s0===undefined||s0===null||s0==="")?-1:num(s0,0,1e6);
    if(sp===null)return{error:"Shop price must be a number"};if(!t)return{error:"Product name is required"};if(price===null)return{error:"Enter a price above 0"};if(mrp===null||sm===null)return{error:"MRP must be a number"};
    return{t,own:b.owner_id?+b.owner_id||null:null,sku:str(b.sku,40),tags:cleanTags(b.tags),price,sp:sp<0?price:sp,sm,mrp,cat:str(b.category,90),opts:[...new Map(str(b.options,120).split(",").map(s=>s.trim()).filter(Boolean).map(x=>[x.toLowerCase(),x])).values()].join(","),ret:b.returns?1:0,desc:str(b.description,3000),dte:str(b.description_te,3000),act:b.active===0||b.active===false?0:1}};
