async function sendMail(env,to,subject,html,text){if(!env.RESEND_API_KEY||!to)return false;const from=env.SUPPORT_FROM||"support@pick-smart.in",ac=new AbortController(),t=setTimeout(()=>ac.abort(),5000);
 try{const r=await fetch(env.RESEND_URL||"https://api.resend.com/emails",{method:"POST",signal:ac.signal,headers:{authorization:"Bearer "+env.RESEND_API_KEY,"content-type":"application/json"},body:JSON.stringify({from:"PickSmart <"+from+">",to:[to],reply_to:from,subject,html,text})});return r.ok}catch(e){return false}finally{clearTimeout(t)}}
async function welcomeMail(env,em,nm,code,pw,existing){const pwl=existing?"Your password: the one you already use on PickSmart":"Your password: "+pw,pwt=existing?"Password: the one you already use on PickSmart":"Password: "+pw;return await sendMail(env,em,"Your PickSmart shop is ready ("+code+")","<p>Hello "+eh(nm)+",</p><p>Welcome to PickSmart. Your shop account is ready.</p><p><b>Shop ID:</b> "+code+"<br><b>Login email:</b> "+eh(em)+"<br><b>"+eh(pwl)+"</b></p><p><b>Log in:</b> <a href=\"https://pick-smart.in/?owner=1#/account\">https://pick-smart.in/?owner=1#/account</a><br><b>Your orders and products:</b> <a href=\"https://pick-smart.in/shop/owner\">https://pick-smart.in/shop/owner</a></p><p>Please change your password after you log in (Account page). Do not share it with anyone.</p><p>PickSmart<br>pick-smart.in</p>","Welcome to PickSmart. Your shop account is ready.\nShop ID: "+code+"\nLogin email: "+em+"\n"+pwt+"\nLog in: https://pick-smart.in/?owner=1#/account\nYour orders and products: https://pick-smart.in/shop/owner\nPlease change your password after you log in.\n\nPickSmart\npick-smart.in")}
