 try{if(env.SHOP_MEDIA){const ist=new Date(now+19800000),day=ist.toISOString().slice(0,10);if(ist.getUTCHours()>=2){const done=await DB.prepare("SELECT v FROM shop_settings WHERE k='backup_day'").first();
  if(!done||done.v!==day){await env.SHOP_MEDIA.put("backup/"+day+".json",JSON.stringify(await dumpAll(DB)),{httpMetadata:{contentType:"application/json"}});await DB.prepare("INSERT INTO shop_settings(k,v) VALUES('backup_day',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v").bind(day).run();
   const l=(await env.SHOP_MEDIA.list({prefix:"backup/"})).objects.map(o=>o.key).sort();for(const k of l.slice(0,Math.max(0,l.length-14)))await env.SHOP_MEDIA.delete(k)}}}}catch(e){}
